Read this token contract and, from the code shown alone, say: (a) who can create tokens, and what limits that; (b) who can move or destroy tokens; (c) what it records; (d) whether the owner can freeze or take anyone's tokens.

```solidity
contract Ticket {
    address public owner;
    uint public constant CAP = 1000000;
    uint public totalSupply;
    mapping(address => uint) public balances;
    event Transfer(address from, address to, uint amount);

    constructor() { owner = msg.sender; }

    function mint(address to, uint amount) public {
        require(msg.sender == owner, "not owner");
        require(totalSupply + amount <= CAP, "cap");
        totalSupply += amount;
        balances[to] += amount;
        emit Transfer(address(0), to, amount);
    }

    function burn(uint amount) public {
        require(amount <= balances[msg.sender], "balance");
        balances[msg.sender] -= amount;
        totalSupply -= amount;
        emit Transfer(msg.sender, address(0), amount);
    }

    function send(address to, uint amount) public {
        require(amount <= balances[msg.sender], "balance");
        balances[msg.sender] -= amount;
        balances[to] += amount;
        emit Transfer(msg.sender, to, amount);
    }
}
```
